  "Suggest a tool": { es: "Sugerir una herramienta", ar: "اقترح أداة", zh: "推荐一个工具", sw: "Pendekeza zana", sv: "Föreslå ett verktyg", de: "Werkzeug vorschlagen", pt: "Sugerir uma ferramenta", fr: "Suggérer un outil" },
  "Read the source": { es: "Leer el código fuente", ar: "اقرأ الكود المصدري", zh: "阅读源代码", sw: "Soma msimbo chanzo", sv: "Läs källkoden", de: "Quellcode lesen", pt: "Ler o código-fonte", fr: "Lire le code source" },
  "Source on GitHub": { es: "Código en GitHub", ar: "الكود على GitHub", zh: "GitHub 上的源代码", sw: "Msimbo kwenye GitHub", sv: "Källkod på GitHub", de: "Quellcode auf GitHub", pt: "Código no GitHub", fr: "Code sur GitHub" },
  "MigaBuilder is an independent project. Claude is a product of Anthropic, which is not affiliated with this site.": { es: "MigaBuilder es un proyecto independiente. Claude es un producto de Anthropic, que no está vinculada a esta web.", ar: "MigaBuilder مشروع مستقل. Claude منتج من Anthropic، وهي غير مرتبطة بهذا الموقع.", zh: "MigaBuilder 是一个独立项目。Claude 是 Anthropic 的产品，Anthropic 与本站没有关联。", sw: "MigaBuilder ni mradi huru. Claude ni bidhaa ya Anthropic, ambayo haihusiani na tovuti hii.", sv: "MigaBuilder är ett oberoende projekt. Claude är en produkt från Anthropic, som inte är knutet till den här webbplatsen.", de: "MigaBuilder ist ein unabhängiges Projekt. Claude ist ein Produkt von Anthropic, das nicht mit dieser Website verbunden ist.", pt: "O MigaBuilder é um projeto independente. O Claude é um produto da Anthropic, que não tem vínculo com este site.", fr: "MigaBuilder est un projet indépendant. Claude est un produit d’Anthropic, qui n’est pas affilié à ce site." },
